    `maxlevel` = LEAST(@LEVEL + @SPREAD, GREATEST(@LEVEL, @LEVEL + ROUND((CAST(`maxlevel` AS SIGNED) - CAST(@MINL AS SIGNED)) * @SPREAD / @SPAN))),
